create_tax_zone.code:
import {taxZones} from 'webcommander-sdk';

const response = await taxZones.createTaxZone(client, {
    tax_zone: {
        name: 'Sydney Metro',
        countries: [{id: 12}],
        states: [{id: 67}],
        post_code: ['2000', '3000'],
    },
});
console.log(response.map.tax_zone.id, response.map.tax_zone.post_code);

